    plan=json.loads((OUT/'plan.json').read_text());summary=json.loads((OUT/'summary.json').read_text());audit=json.loads((OUT/'audit.json').read_text());first=json.loads((PARENT/'attempt-01/unknown-receipt.json').read_text());inventory=json.loads((OUT/'inventory.json').read_text());requirements=load(OUT/'admission-requirements.json.gz');core=load(OUT/'two-lemmas-retained-core.json.gz');samples=load(OUT/'two-lemmas-motif-pilot-6.json.gz');defs={d['name']:d for d in core['definitions']}
