    path=DOC/'commutativity_feasibility.html';path.write_text(doc);exported.insert(0,path);exported+=sorted(HERE.glob('commutativity_*.py'));manifest=dict(status='prepared-for-parent-integration',published=False,scope='Bounded independently audited feasibility only; no target proof/native admission/RL result',all_prior137_files_immutable=True,reader='commutativity_feasibility.html?v=20261011-cf1#result',native_queries=0,target_searches=0,RL_training_runs=0,files=[dict(path=str(p.relative_to(ROOT)),bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest()) for p in exported]);(OUT/'integration.json').write_text(json.dumps(manifest,indent=2)+'\n');print(json.dumps(dict(files=len(exported),html_bytes=path.stat().st_size,reader=manifest['reader'])))
